[
  {
    "alert_id": "ALERT_TDF_TOXICITY_PROXIMAL_TUBULOPATHY",
    "title": "TDF toxicity: low phosphate, proteinuria, bone pain",
    "message": "Guidelines list TDF major toxicities including chronic kidney disease, Fanconi syndrome, decreased bone mineral density, and lower back pain with bone aches as presenting signs. Patient on TDF for 6 years now has serum phosphate 0.78 mmol/L, trace proteinuria, and chronic lower back pain with thigh heaviness worsening over 4 months. Evidence for drug attribution: TDF causes proximal tubular dysfunction leading to phosphaturia and proteinuria, and osteomalacia can manifest as bone pain. Evidence against: creatinine is within normal limits at 112 umol/L, back pain may be occupational from truck driving, and proteinuria could be secondary to uncontrolled hypertension. The combination of hypophosphataemia plus proteinuria in a long-term TDF patient strongly suggests early TDF tubulopathy.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Do renal function tests including eGFR, urine protein-to-creatinine ratio, and serum phosphate trend. If confirmed TDF nephrotoxicity, switch TDF to TAF or alternative per guidelines.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 10, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p10_c1"}
    ]
  },
  {
    "alert_id": "ALERT_TDF_MONITORING_GAP_EGFR",
    "title": "Missing eGFR and annual TDF renal monitoring",
    "message": "Guidelines require serum creatinine and eGFR every 12 months for experienced patients on TDF. Patient has been on TDF for 6 years; creatinine was checked today but eGFR was not calculated or documented. Additionally, serum phosphate was measured today and is low at 0.78 mmol/L, yet the clinician's plan does not address this abnormality or include any follow-up renal monitoring. The plan to review in 6 months without further renal investigation is insufficient given the abnormal phosphate and trace proteinuria findings.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Calculate eGFR from today's creatinine. Schedule renal monitoring including phosphate, proteinuria assessment, and eGFR within 3 months rather than waiting 6 months.",
    "citations": [
      {"page_number": 29, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p29_c1"}
    ]
  },
  {
    "alert_id": "ALERT_IBUPROFEN_TDF_NEPHROTOXICITY",
    "title": "Ibuprofen plus TDF and hypertension increases renal risk",
    "message": "Guidelines list chronic kidney disease and acute kidney injury as TDF major toxicities. Patient is on TDF with emerging signs of renal tubular dysfunction (low phosphate, proteinuria) and uncontrolled hypertension at 146/94 mmHg. The plan recommends PRN ibuprofen for back pain. NSAIDs like ibuprofen can reduce renal perfusion via prostaglandin inhibition, compounding TDF-mediated tubular damage and hypertensive nephropathy. This triple combination of TDF tubulopathy risk, uncontrolled hypertension, and NSAID use creates a compounding renal risk that the current plan does not address.",
    "issue_type": "drug_interaction",
    "severity": "high",
    "recommended_action": "Avoid or limit ibuprofen use given TDF tubulopathy signs and uncontrolled hypertension. Consider paracetamol for pain management. Optimize blood pressure control and renal monitoring.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"}
    ]
  },
  {
    "alert_id": "ALERT_EFV_AMLODIPINE_INTERACTION",
    "title": "EFV may lower amlodipine levels, worsening BP control",
    "message": "Guidelines state efavirenz could potentially decrease dihydropyridine drug levels including amlodipine, though no dose adjustments are required. Patient on EFV plus amlodipine has suboptimal blood pressure at 146/94 mmHg and admits to missing amlodipine doses while travelling. The interaction may further reduce amlodipine efficacy beyond poor adherence. The plan simply refills amlodipine 5 mg without addressing the interaction or considering whether dose adjustment or switching to an alternative antihypertensive is needed.",
    "issue_type": "drug_interaction",
    "severity": "low",
    "recommended_action": "Reinforce amlodipine adherence. If BP remains uncontrolled despite adherence, consider dose increase or switch to an antihypertensive with less EFV interaction.",
    "citations": [
      {"page_number": 44, "chunk_id": "hiv_guidelines_co_infectionscreening.extraction__hiv_guidelines_co_infectionscreening.extraction__p44_c2"}
    ]
  }
]
